class Structure {
  ArrayList<Integer> items;

  public Structure(){ items = new ArrayList<>();}

  public void add(int x){items.add(x);}
  public int sz(){return items.size();}
  public int L(int i){return i*2 + 1;}
  public int R(int i){return i * 2 + 2;}
  public void t1(int i)
  {
    if(i >= items.size())
      return;
    t1(L(i));
    t1(R(i));
    out.print(items.get(i));
  }

  public void t2()
  {
    Queue<Integer> que = new LinkedList<Integer>();
    que.add(0);
    while(!que.isEmpty())
    {
      int x = que.poll();
      if(x >= items.size())
        continue;
      out.print(items.get(x));
      que.add(L(x));
      que.add(R(x));
    }
  }
  public int subSum1(int i)
  {
    if(i >= items.size())
      return 0;
    return subSum1(L(i)) + subSum1(R(i)) + items.get(i);
  }

  public int subSum2(int i, Integer[] memo)
  {
    if(i >= items.size())
      return 0;
    if(memo[i] != null)
      return memo[i];
    memo[i] = subSum2(L(i), memo) + subSum2(R(i), memo) + items.get(i);
    return memo[i];
  }
}

